"""Weekly timesheet lines, one per worker, busiest first."""

from typing import Dict, List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter


# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    check_shifts(shifts)
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    return [
        timesheet_row(name, counts[name], totals[name])
        for name in busiest_first(totals)
    ]


# ---
def check_shifts(shifts: List[Shift]) -> None:
    """Refuse an empty list or a blank worker name."""
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")


# ---
def busiest_first(totals: Dict[str, int]) -> List[str]:
    """Most minutes first, ties in alphabetical order."""
    names = sorted(totals)
    return sorted(names, key=lambda name: -totals[name])


# ---
def timesheet_row(
    name: str, count: int, minutes: int
) -> str:
    """Name, shift count and hours to one decimal place."""
    hours = minutes / 60
    noun = "shift" if count == 1 else "shifts"
    return f"{name}: {count} {noun}, {hours:.1f} hours"
